import os
all_files = []
for root, dirs, files in os.walk('/'):
    if root.startswith('/proc') or root.startswith('/sys') or root.startswith('/dev'):
        continue
    for f in files:
        all_files.append(os.path.join(root, f))

print('Total files on disk:', len(all_files))
for f in all_files:
    if not (f.startswith('/usr') or f.startswith('/lib') or f.startswith('/etc') or f.startswith('/var')):
        print('Non-standard file:', f)
